///////////////////////////////////////////////////////////
// 2D geometry helpers
///////////////////////////////////////////////////////////
float cross2D(vec2 a, vec2 b)
{
    return a.x*b.y - a.y*b.x;
}
bool pointInTriangle(vec2 P, vec2 A, vec2 B, vec2 C)
{
    float areaABC = abs(cross2D(B - A, C - A));
    float areaPBC = abs(cross2D(B - P, C - P));
    float areaAPC = abs(cross2D(P - A, C - A));
    float areaABP = abs(cross2D(B - A, P - A));
    return (areaPBC + areaAPC + areaABP <= areaABC + 0.0001);
}

// distance from P to an arm pivot->angle->armLen
float distanceToArm(vec2 P, vec2 pivot, float angle, float armLen)
{
    vec2 dir = vec2(cos(angle), sin(angle));
    float t  = dot(P - pivot, dir);
    if(t<0.0 || t>armLen) return 99999.;
    return distance(P, pivot + t*dir);
}

// distance from P to line-segment A->B
float distanceToSegment(vec2 P, vec2 A, vec2 B)
{
    vec2 AB = B - A;
    float t = dot(P - A, AB)/dot(AB,AB);
    t=clamp(t,0.0,1.0);
    return distance(P, A + t*AB);
}

///////////////////////////////////////////////////////////
// We draw arms + face with a "cell-based" approach (raster).
// We'll incorporate the globalAngle so the entire corner is rotated.
///////////////////////////////////////////////////////////
vec3 getCellColorAt(vec2 cellCenter, vec2 pivot, float vertAngle, float globalAngle)
{
    float armLen = 200.0;

    // horizontal arm => base angle=0
    float angleH = globalAngle + 0.0;
    // vertical arm => base angle=vertAngle
    float angleV = globalAngle + vertAngle;

    // default => grey
    vec3 color = vec3(0.8);

    // tips
    vec2 tipH = pivot + armLen*vec2(cos(angleH), sin(angleH));
    vec2 tipV = pivot + armLen*vec2(cos(angleV), sin(angleV));
    // midpoints
    vec2 midH = mix(pivot, tipH, 0.5);
    vec2 midV = mix(pivot, tipV, 0.5);

    // White triangular face
    bool inFace = pointInTriangle(cellCenter, pivot, midH, midV);
    if(inFace) color = vec3(1.0);

    // Thick arms
    float thick = 18.0;
    // red horizontal
    if(distanceToArm(cellCenter, pivot, angleH, armLen)<=thick)
        color = vec3(0.0,0.0,1.0);
    // blue vertical
    if(distanceToArm(cellCenter, pivot, angleV, armLen)<=thick)
        color = vec3(0.0,0.0,1.0);
    // green line midH->midV
    if(distanceToSegment(cellCenter, midH, midV)<=thick)
        color = vec3(0.000,0.518,1.000);

    return color;
}

///////////////////////////////////////////////////////////
// Circle overlay logic
// - pivot => black fill + grey ring
// - other points => white fill + grey ring
//   BUT if it's the "middle of green line" and arms are acute => red fill
///////////////////////////////////////////////////////////
vec4 drawPivotCircle(vec2 fragCoord, vec2 pivot)
{
    float radius=10.0;
    float border=2.0;
    float d = distance(fragCoord, pivot);

    if(d<radius)
        return vec4(0.0,0.0,0.0,1.0);  // black fill
    if(d<radius+border)
        return vec4(0.5,0.5,0.5,1.0); // grey ring
    return vec4(-1.0);
}

// White circle w/ grey ring
vec4 drawWhiteCircle(vec2 fragCoord, vec2 cPos)
{
    float r=10.0, b=2.0;
    float d= distance(fragCoord, cPos);
    if(d<r)
        return vec4(1.0);
    if(d<r+b)
        return vec4(0.5,0.5,0.5,1.0);
    return vec4(-1.0);
}

// Red circle if angle is acute, else white circle
vec4 drawMidGreenCircle(vec2 fragCoord, vec2 cPos, bool isAcute)
{
    float r=10.0, b=2.0;
    float d= distance(fragCoord, cPos);
    if(d<r)
    {
        // if angle is acute => red fill, else white fill
        if(isAcute) return vec4(1.0,0.0,0.0,1.0);
        else        return vec4(1.0,1.0,1.0,1.0);
    }
    else if(d<r+b)
    {
        // grey ring
        return vec4(0.5,0.5,0.5,1.0);
    }
    return vec4(-1.0);
}

///////////////////////////////////////////////////////////
// Overlays circles in normal (smooth) rendering
// The special logic: midG circle => red fill if arms are acute
///////////////////////////////////////////////////////////
vec4 overlayCircles(
    in vec2 fragCoord,
    in vec2 pivot,
    in vec2 tipH,
    in vec2 tipV,
    in vec2 midH,
    in vec2 midV,
    in vec2 midG,
    bool armsAcute,
    in vec4 baseColor)
{
    // 1) pivot circle on top
    vec4 cP = drawPivotCircle(fragCoord, pivot);
    if(cP.x>=0.0) return cP;

    // 2) tipH => normal white circle
    vec4 c = drawWhiteCircle(fragCoord, tipH);
    if(c.x>=0.0) return c;

    // 3) tipV => normal white circle
    c = drawWhiteCircle(fragCoord, tipV);
    if(c.x>=0.0) return c;

    // 4) midH => normal white circle
    c = drawWhiteCircle(fragCoord, midH);
    if(c.x>=0.0) return c;

    // 5) midV => normal white circle
    c = drawWhiteCircle(fragCoord, midV);
    if(c.x>=0.0) return c;

    // 6) midG => red if armsAcute, else white
    c = drawMidGreenCircle(fragCoord, midG, armsAcute);
    if(c.x>=0.0) return c;

    // if none => keep base color
    return baseColor;
}

///////////////////////////////////////////////////////////
// Compute the smaller interior angle (0..π) between arms
//   horizontal=0°, vertical=vertAngle
//   an angle >π is reflex, so we do (2π - angle).
///////////////////////////////////////////////////////////
float getArmsSmallerAngle(float vertAngle)
{
    // angle between arms if horizontal=0 => simply vertAngle in [0..2π]
    float raw = mod(vertAngle, 6.283185307);
    if(raw>3.1415926535)
        raw = 6.283185307 - raw;
    // now raw in [0..π]
    return raw;
}

///////////////////////////////////////////////////////////
// Main pass
///////////////////////////////////////////////////////////
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    //----------------------------------
    // 1) Read pivot + angles
    //----------------------------------
    vec4 stA = texelFetch(iChannel0, ivec2(0,0), 0);
    // pivot in [0..1], verticalAngle, globalAngle in [0..1]
    vec2 pivotN   = stA.xy;
    float vertNor = stA.z;
    float globNor = stA.w;

    float vertAngle = vertNor*6.283185307;
    float globAngle = globNor*6.283185307;

    vec2 pivot = pivotN * iResolution.xy;

    //----------------------------------
    // 2) Draw cell-based background
    //----------------------------------
    float cellSize = 18.0;
    vec2  cellCoord  = floor(fragCoord/cellSize);
    vec2  cellOrigin = cellCoord*cellSize;
    vec2  cellCenter = cellOrigin + 0.5*cellSize;

    // arms+face in blocky style
    vec3 cellColor = getCellColorAt(cellCenter, pivot, vertAngle, globAngle);

    // white grid lines
    float lineW=1.0;
    vec2 local=fragCoord - cellOrigin;
    bool isLine = (local.x<lineW)||(local.y<lineW);

    fragColor = isLine? vec4(1.0) : vec4(cellColor,1.0);

    //----------------------------------
    // 3) Overlay circles in smooth style
    //----------------------------------
    float armLen=200.0;
    // angles
    float angleH = globAngle + 0.0;       // horizontal
    float angleV = globAngle + vertAngle; // vertical

    vec2 tipH = pivot + armLen*vec2(cos(angleH), sin(angleH));
    vec2 tipV = pivot + armLen*vec2(cos(angleV), sin(angleV));
    vec2 midH = mix(pivot, tipH, 0.5);
    vec2 midV = mix(pivot, tipV, 0.5);
    vec2 midG = mix(midH, midV, 0.5);

    // Check if arms are acute => < 90°
    float angleBetween = getArmsSmallerAngle(vertAngle);
    bool armsAcute = (angleBetween < 1.57079632679); // pi/2

    fragColor = overlayCircles(fragCoord, pivot, tipH, tipV, midH, midV, midG, armsAcute, fragColor);
}

///////////////////////////////////////////////////////////
// Buffer A: Stores pivot, angles, etc.
//
// iChannel0 -> Buffer A (ping-pong)
// iChannel3 -> Keyboard
///////////////////////////////////////////////////////////

// 1) Check if a key is pressed (GLSL function)
bool isKeyPressed(int kc)
{
    // Shadertoy Keyboard is iChannel3: a 256x1 texture
    // Key 'kc' is pressed if .x > 0.5
    return texture(iChannel3, vec2((float(kc) + 0.5) / 256.0, 0.5)).x > 0.5;
}

// 2) Minimal pseudo-random generator
//    NOTE: We do "inout float seed" so it modifies the seed.
float rand(inout float seed)
{
    float r = fract(sin(seed * 1234.5678) * 43758.5453123);
    seed += 0.12345 + r * 0.98765;
    return r;
}

// We'll store the updated seed in a global variable so that
// pixel (1,0) can write it into the texture. This trick
// works in Shadertoy to keep track of a single value
// across multiple pixel invocations in the same frame.
float gUpdatedSeed = 0.0;

// 3) Up/Down reversed arrow movement
vec2 getKeyboardOffset()
{
    // Left=37, Up=38, Right=39, Down=40
    bool left  = isKeyPressed(37);
    bool up    = isKeyPressed(38);
    bool right = isKeyPressed(39);
    bool down  = isKeyPressed(40);

    float shift = 50.0 / min(iResolution.x, iResolution.y);
    vec2 offset = vec2(0.0);

    if (left)  offset.x -= shift;
    if (right) offset.x += shift;
    if (up)    offset.y += shift;  // reversed
    if (down)  offset.y -= shift;  // reversed

    return offset;
}

///////////////////////////////////////////////////////////
// Main storage logic
///////////////////////////////////////////////////////////
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 cell = ivec2(fragCoord);

    // On the first frame, initialize
    if(iFrame == 0)
    {
        // We store pivot & angles in pixel (0,0),
        // and oldRKey + random seed in pixel (1,0)
        if(all(equal(cell, ivec2(0,0))))
        {
            // pivot=(0.5,0.5), verticalAngle=80° => 80/360 ~ 0.2222, globalAngle=0
            fragColor = vec4(0.5, 0.5, 80.0/360.0, 0.0);
        }
        else if(all(equal(cell, ivec2(1,0))))
        {
            // oldR=0, seed=1234
            fragColor = vec4(0.0, 1234.0, 0.0, 0.0);
        }
        else
        {
            fragColor = vec4(0.0);
        }
        return;
    }

    // Otherwise, read old state
    vec4 oldA = texelFetch(iChannel0, ivec2(0,0), 0); // pivot, angles
    vec4 oldB = texelFetch(iChannel0, ivec2(1,0), 0); // oldR, seed

    // Default: pass through old data
    fragColor = texelFetch(iChannel0, cell, 0);

    //------------------------------------------------------------------
    // We'll gather everything up front, do the toggle logic once, then
    // store final results in either pixel(0,0) or pixel(1,0).
    //------------------------------------------------------------------
    // oldA: pivot=(x,y), verticalAngle=oldA.z in [0..1], globalAngle=oldA.w in [0..1]
    vec2 pivotN   = oldA.xy; 
    float vertNor = oldA.z;  // fraction of 2π
    float globNor = oldA.w;  // fraction of 2π
    float vertAngle  = vertNor * 6.283185307; 
    float globalAng  = globNor * 6.283185307;

    // oldB: oldR=oldB.x, seed=oldB.y
    float oldR   = oldB.x;
    float seed   = oldB.y;

    // For the new frame, let's define placeholders
    // We'll fill them with updated values if needed.
    float newVertNor = vertNor;
    float newGlobNor = globNor;
    float newR       = 0.0;   // will be set based on isKeyPressed
    float newSeed    = seed;  // if we call rand, we'll update it

    // Check the keyboard R state
    bool rNow   = isKeyPressed(82);  // R=82
    bool wasR   = (oldR > 0.5);
    bool rising = (rNow && !wasR);

    // We'll also gather pivot updates & mouse rotation
    vec2 newPivotN = pivotN;
    newPivotN += getKeyboardOffset();
    newPivotN = clamp(newPivotN, vec2(0.0), vec2(1.0));

    if(iMouse.z >= 0.0 && iMouse.x >= 0.0)
    {
        vec2 pivotS = newPivotN * iResolution.xy;
        vertAngle = atan(iMouse.y - pivotS.y, iMouse.x - pivotS.x);
    }

    // Now do the toggle logic: random vs 0
    if(rising)
    {
        // If globalAng ~0 => pick random, else => revert to 0
        if(abs(globalAng) < 0.0001)
        {
            float r = rand(newSeed);  // modifies newSeed in-place
            globalAng = r * 6.283185307; // random angle in [0..2π]
        }
        else
        {
            globalAng = 0.0;
        }
    }

    // Convert angles back to [0..1] for storage
    newVertNor = fract(vertAngle / 6.283185307);
    newGlobNor = fract(globalAng / 6.283185307);

    // Also store the new "R pressed" state
    newR = rNow ? 1.0 : 0.0;

    // We also want to store the final updated seed in gUpdatedSeed
    gUpdatedSeed = newSeed;


    //------------------------------------------------------------------
    // Now store final data depending on which pixel we're writing:
    //------------------------------------------------------------------
    if(all(equal(cell, ivec2(0,0))))
    {
        // pixel(0,0) => pivot & angles
        fragColor = vec4(newPivotN, newVertNor, newGlobNor);
    }
    else if(all(equal(cell, ivec2(1,0))))
    {
        // pixel(1,0) => oldR, seed
        fragColor = vec4(newR, gUpdatedSeed, 0.0, 0.0);
    }
    // else => pass old data (already in fragColor by default)
}
